import http from "node:http";
import { URL } from "node:url";

const PORT = Number(process.env.PORT) || 3000;
const CLICKHOUSE_URL = (process.env.CLICKHOUSE_URL || "http://localhost:8123").replace(/\/$/, "");

const MAX_LIMIT = 1000;

async function clickhousePost(sql) {
  const res = await fetch(CLICKHOUSE_URL, {
    method: "POST",
    headers: { "Content-Type": "text/plain; charset=utf-8" },
    body: sql,
  });
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`ClickHouse HTTP ${res.status}: ${text.slice(0, 500)}`);
  }
  return text;
}

async function getTotalCount() {
  const raw = await clickhousePost(
    "SELECT count() AS total FROM analytics.events FORMAT JSON",
  );
  const parsed = JSON.parse(raw);
  const row = parsed.data?.[0];
  return Number(row?.total ?? 0);
}

async function getPage(limit, offset) {
  const sql =
    "SELECT event_id, event_ts, event_type, user_id " +
    "FROM analytics.events " +
    "ORDER BY event_ts ASC, event_id ASC " +
    `LIMIT ${limit} OFFSET ${offset} ` +
    "FORMAT JSONEachRow";
  const raw = await clickhousePost(sql);
  const lines = raw.split("\n").filter((l) => l.trim().length > 0);
  return lines.map((line) => JSON.parse(line));
}

function parsePagination(searchParams) {
  let limit = Number(searchParams.get("limit"));
  let offset = Number(searchParams.get("offset"));
  if (!Number.isFinite(limit) || limit < 1) limit = 20;
  if (limit > MAX_LIMIT) limit = MAX_LIMIT;
  if (!Number.isFinite(offset) || offset < 0) offset = 0;
  return { limit: Math.floor(limit), offset: Math.floor(offset) };
}

const server = http.createServer(async (req, res) => {
  if (req.method !== "GET") {
    res.writeHead(405, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Method not allowed" }));
    return;
  }

  let pathname;
  try {
    pathname = new URL(req.url || "/", `http://127.0.0.1:${PORT}`).pathname;
  } catch {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Bad request" }));
    return;
  }

  if (pathname !== "/api/events") {
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found" }));
    return;
  }

  try {
    const url = new URL(req.url || "/", `http://127.0.0.1:${PORT}`);
    const { limit, offset } = parsePagination(url.searchParams);

    const [total, rows] = await Promise.all([getTotalCount(), getPage(limit, offset)]);

    const hasMore = offset + rows.length < total;
    const body = JSON.stringify({
      data: rows,
      total,
      hasMore,
    });

    res.writeHead(200, {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
    });
    res.end(body);
  } catch (err) {
    res.writeHead(500, { "Content-Type": "application/json" });
    res.end(
      JSON.stringify({
        error: "Internal server error",
        message: err instanceof Error ? err.message : String(err),
      }),
    );
  }
});

server.listen(PORT, "0.0.0.0", () => {
  process.stderr.write(`analytics API listening on ${PORT}\n`);
});

